const professions={pesca:'Pesca',campi:'Campi',cantiere:'Cantiere',consegne:'Consegne',mare:'Mare',sport:'Sport'};
export function professionLabel(value){return Object.hasOwn(professions,value)?` <span class="profession-label" title="Dichiarato dall’utente">${professions[value]}</span>`:''}
export function professionGuide(){return '<section class="profession-guide"><h2>Chi ci lavora</h2><p>Pesca, campi, cantiere, consegne, mare o sport: l’attività è facoltativa e <strong>dichiarata dall’utente</strong>, non verificata. Puoi toglierla dal Profilo in qualsiasi momento.</p><p>Può dare fino a 1,5 volte il peso normale nella sintesi dei fenomeni pertinenti. Non aumenta persone o conferme, non dà accesso a funzioni e non rende una segnalazione una misura ufficiale.</p></section>'}
export function professionProfile(){return `<section class="card profession-profile"><h2>Chi ci lavora</h2><p>Il meteo fa parte della tua attività?</p><form id="profession-form"><label for="profession-select">Attività facoltativa · dichiarata dall’utente</label><select id="profession-select" disabled><option value="">Nessuna</option>${Object.entries(professions).map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select><p>Non verificata. Puoi toglierla quando vuoi scegliendo “Nessuna”.</p><button type="submit" disabled>Salva attività</button><p id="profession-status" role="status">Carico la tua scelta…</p></form><a href="#guida">Come viene usata</a></section>`}
export async function bindProfession(ctx){
 const form=document.querySelector('#profession-form');if(!form||form.dataset.bound)return;form.dataset.bound='true';
 const select=form.querySelector('select'),button=form.querySelector('button'),status=form.querySelector('[role=status]');
 async function request(method,body){const r=await fetch('/api/profilo',{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Profilo non disponibile.');return d}
 async function load(){button.disabled=true;select.disabled=true;try{await ctx.api('sky/session',{});const d=await request('GET');if(!form.isConnected)return;select.value=d.mestiere||'';select.disabled=false;button.disabled=false;button.textContent='Salva attività';status.textContent='La scelta viene salvata nella tua sessione.'}catch(e){if(form.isConnected){status.textContent=e.message;button.textContent='Riprova';button.disabled=false}}}
 form.onsubmit=async e=>{e.preventDefault();if(select.disabled){await load();return}button.disabled=true;const chosen=select.value;select.disabled=true;try{await request('PATCH',{mestiere:chosen||null});if(form.isConnected)status.textContent=chosen?'Attività salvata · dichiarata dall’utente.':'Attività rimossa dalle segnalazioni.';ctx.changed?.()}catch(e){if(form.isConnected)status.textContent=e.message}finally{if(form.isConnected){button.disabled=false;select.disabled=false}}};
 await load();
}
